@@ -0,0 +1,22 @@
+import { beforeEach, expect, test } from 'bun:test';
+import { clear, load, save } from './storage';
+
+beforeEach(() => clear());
+
+test('saves and loads the same list', () => {
+  save([{ id: 1, title: 'a', done: false }]);
+  expect(load()).toEqual([{ id: 1, title: 'a', done: false }]);
+});
+
+test('returns an empty list when nothing is stored', () => {
+  expect(load()).toEqual([]);
+});
+
+test('survives malformed JSON', () => {
+  localStorage.setItem('sky-todo:v1', '{not json');
+  expect(load()).toEqual([]);
+});
+
+test('survives a non-array payload', () => {
+  localStorage.setItem('sky-todo:v1', '{"a":1}');
+  expect(load()).toEqual([]);
+});
